  private prices = new Map<number, number>();
  private latest = 0;

  update(timestamp: number, price: number): void {
    this.prices.set(timestamp, price);
    this.latest = Math.max(this.latest, timestamp);
  }

  current(): number {
    return this.prices.get(this.latest)!;
  }

  maximum(): number {
    let best = -Infinity;
    for (const p of this.prices.values()) best = Math.max(best, p);
    return best;
  }

  minimum(): number {
    let best = Infinity;
    for (const p of this.prices.values()) best = Math.min(best, p);
    return best;
  }
}

