class Heap {
  private a: [number, number][] = [];
  constructor(private less: (x: [number, number], y: [number, number]) => boolean) {}
  top(): [number, number] { return this.a[0]; }
  push(v: [number, number]): void {
    const a = this.a;
    a.push(v);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.less(a[i], a[p])) break;
      [a[i], a[p]] = [a[p], a[i]];
      i = p;
    }
  }
  pop(): void {
    const a = this.a, last = a.pop()!;
    if (a.length === 0) return;
    a[0] = last;
    let i = 0;
    while (true) {
      const l = 2 * i + 1, r = l + 1;
      let m = i;
      if (l < a.length && this.less(a[l], a[m])) m = l;
      if (r < a.length && this.less(a[r], a[m])) m = r;
      if (m === i) break;
      [a[i], a[m]] = [a[m], a[i]];
      i = m;
    }
  }
}

class PriceTicker {
  private prices = new Map<number, number>();
  private latest = 0;
  private hi = new Heap((x, y) => x[0] > y[0]);
  private lo = new Heap((x, y) => x[0] < y[0]);

  update(timestamp: number, price: number): void {
    this.prices.set(timestamp, price);
    this.latest = Math.max(this.latest, timestamp);
    this.hi.push([price, timestamp]);
    this.lo.push([price, timestamp]);
  }

  current(): number {
    return this.prices.get(this.latest)!;
  }

  private clean(h: Heap): number {
    // drop entries whose timestamp was corrected to another price
    while (this.prices.get(h.top()[1]) !== h.top()[0]) h.pop();
    return h.top()[0];
  }

  maximum(): number { return this.clean(this.hi); }
  minimum(): number { return this.clean(this.lo); }
}

